UPDATE public.profiles SET
  occupation='נגרות', headline='נגר אומן — רהיטים בהזמנה אישית', years_experience=18, is_verified=true,
  bio='נגר עם 18 שנות ניסיון, מתמחה ברהיטים מעץ מלא בהזמנה אישית. הסטודיו שלי בדרום תל אביב ואני מחפש מתלמד עם ידיים טובות ורצון ללמוד מקצוע מהיסוד — מבחירת העץ ועד הגימור.',
  workload='משרה מלאה', availability='ימים א׳-ה׳, 08:00-17:00',
  skills='["רהיטים","עץ מלא","גימור","עבודת יד"]'::jsonb
WHERE id='d0000000-0000-4000-a000-000000000001';

UPDATE public.profiles SET
  occupation='חשמלאות', headline='חשמלאי מוסמך — מגורים, מסחרי ותשתיות', years_experience=22, is_verified=true,
  bio='חשמלאי מוסמך עם 22 שנות ניסיון בחיפה והצפון. עובד על פרויקטים של מגורים, מסחר ותשתיות. מחפש מתמחה רציני שרוצה להיכנס לתחום עם ביקוש קבוע ורישוי מקצועי בסופו.',
  workload='משרה מלאה', availability='גמיש',
  skills='["חשמל תלת-פאזי","לוחות","תשתיות","בטיחות"]'::jsonb
WHERE id='d0000000-0000-4000-a000-000000000002';

UPDATE public.profiles SET
  occupation='אינסטלציה', headline='אינסטלטור — צנרת, ביוב ומערכות מים', years_experience=15,
  bio='אינסטלטור עצמאי כבר 15 שנה באזור השפלה. מטפל בכל תחומי הצנרת — מדליפות ועד מערכות שלמות בבנייה חדשה. מחפש מישהו שרוצה ללמוד מקצוע פרקטי עם עבודה שלא נגמרת.',
  workload='משרה מלאה', availability='ימים א׳-ו׳',
  skills='["צנרת","ביוב","דודי שמש","איתור נזילות"]'::jsonb
WHERE id='d0000000-0000-4000-a000-000000000003';

UPDATE public.profiles SET
  occupation='מיזוג אוויר', headline='טכנאי מזגנים — התקנה ותחזוקה', years_experience=12, is_verified=true,
  bio='טכנאי מיזוג אוויר עם 12 שנות ניסיון. עונת הקיץ מביאה יותר עבודה ממה שאני יכול לקחת לבד, אז אני מחפש מתלמד שרוצה ללמוד מקצוע עם ביקוש ענק ורווחיות גבוהה.',
  workload='משרה מלאה', availability='כולל שישי בעונה',
  skills='["מיני מרכזי","מולטי","תחזוקה","גז קירור"]'::jsonb
WHERE id='d0000000-0000-4000-a000-000000000004';

UPDATE public.profiles SET
  occupation='ריתוך ומסגרות', headline='מסגר ורתך — מעקות, שערים ומבני פלדה', years_experience=20,
  bio='מסגר ורתך עם 20 שנות ניסיון בבאר שבע והדרום. מייצר מעקות, שערים ומבני פלדה. מחפש חניך שרוצה ללמוד ריתוך אמיתי — לא סרטונים ביוטיוב, עבודה בשטח מהיום הראשון.',
  workload='משרה מלאה', availability='ימים א׳-ה׳',
  skills='["ריתוך CO2","נירוסטה","מבני פלדה","מעקות"]'::jsonb
WHERE id='d0000000-0000-4000-a000-000000000005';

UPDATE public.profiles SET
  occupation='שיפוצים ובנייה', headline='קבלן שיפוצים — ניהול פרויקט מא׳ ועד ת׳', years_experience=16, is_verified=true,
  bio='קבלן שיפוצים ותיק בירושלים, מנהל צוות של 4 עובדים. מחפש מישהו שרוצה להבין איך פרויקט שיפוץ עובד באמת — מהצעת מחיר ועד מסירה, כולל עבודה מול לקוחות וקבלני משנה.',
  workload='משרה מלאה', availability='גמיש',
  skills='["ניהול פרויקט","גבס","ריצוף","תמחור"]'::jsonb
WHERE id='d0000000-0000-4000-a000-000000000006';

INSERT INTO public.opportunities (owner_id, type, title, location, work_hours, about_work, requirements, mentee_will_learn, pay_amount, pay_period, status, created_at)
VALUES
  ('d0000000-0000-4000-a000-000000000001','mentor_offer','דרוש מתלמד לנגרות — רהיטים בהזמנה אישית','תל אביב','משרה מלאה','סטודיו לנגרות בדרום תל אביב. עבודה על רהיטים מעץ מלא בהזמנה אישית — שולחנות, ספריות, מטבחים. תלמד מבחירת העץ ועד הגימור הסופי.','ידיים טובות, רצון ללמוד, זמינות למשרה מלאה. ניסיון קודם לא חובה.','עבודה עם כלי יד וכלים חשמליים, קריאת שרטוטים, גימור מקצועי, עבודה מול לקוחות.',55,'hour','active', now() - interval '24 days'),
  ('d0000000-0000-4000-a000-000000000002','mentor_offer','חשמלאי מוסמך מחפש מתמחה — חיפה והצפון','חיפה','משרה מלאה','עבודה על פרויקטים של מגורים, מסחר ותשתיות בכל הצפון. ליווי צמוד עד לרישוי מקצועי.','רצינות, אחריות, רישיון נהיגה יתרון.','חיווט, לוחות חשמל, עבודה עם תשתיות, תקני בטיחות, הכנה לבחינות רישוי.',60,'hour','active', now() - interval '21 days'),
  ('d0000000-0000-4000-a000-000000000003','mentor_offer','אינסטלטור מחפש מתמחה — ראשון לציון והשפלה','ראשון לציון','משרה מלאה','עבודה מגוונת בצנרת — תיקוני דליפות, החלפת מערכות, אינסטלציה בבנייה חדשה. אף יום לא דומה לשני.','כושר גופני סביר, ידיים טובות, רצון לעבוד בשטח.','צנרת מים וביוב, איתור נזילות, התקנת דודי שמש, עבודה עם לקוחות.',50,'hour','active', now() - interval '17 days'),
  ('d0000000-0000-4000-a000-000000000004','mentor_offer','טכנאי מזגנים — עונת הקיץ מתחילה, פתח תקווה','פתח תקווה','משרה מלאה','עונת השיא מתחילה ויש יותר עבודה ממה שאני יכול לקחת לבד. הזדמנות ללמוד מקצוע עם ביקוש קבוע ורווחיות גבוהה.','זמינות מיידית, נכונות לעבוד בקיץ כולל שישי.','התקנת מזגנים, תחזוקה, טעינת גז, אבחון תקלות, שירות לקוחות.',55,'hour','active', now() - interval '13 days'),
  ('d0000000-0000-4000-a000-000000000004','mentor_offer','דרוש עוזר לתחזוקת מערכות מיזוג מסחריות','פתח תקווה','חלקי','עבודת תחזוקה שוטפת במערכות מיזוג מסחריות — קניונים, משרדים. מתאים גם למי שרוצה להתחיל בהיקף חלקי.','אמינות, דייקנות.','תחזוקה מונעת, ניקוי מערכות, בדיקות תקופתיות.',45,'hour','active', now() - interval '11 days'),
  ('d0000000-0000-4000-a000-000000000005','mentor_offer','מסגר ורתך מחפש חניך — באר שבע והדרום','באר שבע','משרה מלאה','מסגריה עם עבודה קבועה — מעקות, שערים, מבני פלדה. עבודה בשטח מהיום הראשון, לא רק צפייה.','כוח פיזי, רצון ללמוד, לא מפחד מעבודה מלכלכת.','ריתוך CO2 ונירוסטה, קריאת שרטוטים, הרכבת מבני פלדה, גימור.',52,'hour','active', now() - interval '8 days'),
  ('d0000000-0000-4000-a000-000000000006','mentor_offer','קבלן שיפוצים מחפש יד ימין — ירושלים','ירושלים','משרה מלאה','הזדמנות ללמוד ניהול פרויקט שיפוץ מא׳ ועד ת׳ — מהצעת מחיר ועד מסירת המפתח, כולל עבודה מול לקוחות וספקים.','ראש גדול, יחסי אנוש טובים, רישיון נהיגה.','גבס, ריצוף, צבע, תמחור עבודות, ניהול צוות, עבודה מול לקוחות.',50,'hour','active', now() - interval '4 days'),
  ('d0000000-0000-4000-a000-000000000001','mentor_offer','עוזר/ת לסדנת נגרות — פרויקטים קטנים','תל אביב','חלקי','חיפוש עזרה לפרויקטים קטנים בסדנה — מסגרות, מדפים, תיקוני רהיטים. מתאים לסטודנט/ית או מי שרוצה להתנסות.','זמינות של יומיים בשבוע לפחות.','יסודות עבודת העץ, שימוש בכלים, בטיחות בסדנה.',48,'hour','active', now() - interval '3 days'),
  ('d0000000-0000-4000-a000-000000000002','mentor_offer','דרוש חשמלאי מתחיל לפרויקט בנייה — קריות','חיפה','משרה מלאה','פרויקט בנייה חדש בקריות, עבודה לחצי שנה לפחות עם אפשרות להמשך. ליווי צמוד של חשמלאי מנוסה.','נכונות לעבודה פיזית, הגעה עצמאית לאתר.','חיווט בבנייה חדשה, קריאת תוכניות חשמל, עבודת צוות באתר.',58,'hour','active', now() - interval '1 days');
